using System.Security.Cryptography;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json.Serialization;
using Aegis.Configuration.Application;
using Aegis.Configuration.Domain;
using Aegis.Configuration.Infrastructure;
using Common.Secrets;

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);
builder.Services.ConfigureHttpJsonOptions(o => o.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));
string contractDirectory = builder.Configuration["AegisConfiguration:ContractDirectory"] ?? Path.Combine(builder.Environment.ContentRootPath, "contracts");
string instructionDirectory = builder.Configuration["AegisConfiguration:InstructionDirectory"] ?? Path.GetFullPath(Path.Combine(builder.Environment.ContentRootPath, "..", "..", "instruction-packs"));
builder.Services.AddCommonSecrets(builder.Configuration);
DirectoryContractStore contractStore = new(contractDirectory);
builder.Services.AddSingleton<IConfigurationContractStore>(contractStore);
builder.Services.AddSingleton<IConfigurationContractRegistrationStore>(contractStore);
builder.Services.AddSingleton(new InstructionPackCatalog(instructionDirectory));
builder.Services.AddSingleton<ConfigurationEvaluator>();
builder.Services.AddSingleton<CommissioningService>();
builder.Services.AddSingleton<CommissioningReportRenderer>();
builder.Services.AddSingleton<ContractValidator>();
WebApplication app = builder.Build();
app.MapGet("/", async (IConfigurationContractStore store, ConfigurationEvaluator evaluator, CancellationToken ct) => { var contracts=await store.LoadAllAsync(ct); var rows=new List<(ApplicationConfigurationContract Contract,ConfigurationEvaluation Evaluation)>(); foreach(var c in contracts.OrderBy(x=>x.DisplayName)) rows.Add((c,await evaluator.EvaluateAsync(c,ct))); string cards=rows.Count==0?"<section class='panel empty'><h2>NO APPLICATIONS REGISTERED</h2><p>Start an application to publish its configuration contract.</p></section>":string.Join("",rows.Select(x=>RenderApplication(x.Contract,x.Evaluation))); return Html(Page("Applications","Applications › Configuration Registry",cards,"applications")); });
app.MapGet("/applications/{applicationId}", async (string applicationId,IConfigurationContractStore store,ConfigurationEvaluator evaluator,CancellationToken ct)=>{var c=(await store.LoadAllAsync(ct)).FirstOrDefault(x=>string.Equals(x.ApplicationId,applicationId,StringComparison.OrdinalIgnoreCase)); if(c is null)return Results.NotFound(); return Html(Page(c.DisplayName,$"Applications › {E(c.DisplayName)}",RenderApplication(c,await evaluator.EvaluateAsync(c,ct),true),"applications"));});
app.MapGet("/runbooks", async (IConfigurationContractStore store,CancellationToken ct)=>{var contracts=await store.LoadAllAsync(ct); string body=contracts.Count==0?"<section class='panel empty'><h2>NO RUNBOOKS AVAILABLE</h2></section>":"<section class='panel'><div class='sectiontitle'>Configuration Runbooks</div><div class='runbooklist'>"+string.Join("",contracts.OrderBy(x=>x.DisplayName).Select(x=>$"<a class='btn' href='/runbooks/{Uri.EscapeDataString(x.ApplicationId)}'>{E(x.DisplayName)} <span class='muted'>· {E(x.Version)}</span></a>"))+"</div></section>"; return Html(Page("Runbooks","Runbooks",body,"runbooks"));});
app.MapGet("/runbooks/{applicationId}", async (string applicationId,CommissioningService service,InstructionPackCatalog packs,CommissioningReportRenderer renderer,CancellationToken ct)=>{var s=(await service.EvaluateAllAsync(ct)).FirstOrDefault(x=>string.Equals(x.ApplicationId,applicationId,StringComparison.OrdinalIgnoreCase)); if(s is null)return Results.NotFound(); string markdown=renderer.RenderMarkdown(s,await packs.FindAsync(s.ApplicationId,s.ApplicationVersion,ct)); return Html(Page("Runbook",$"Applications › {E(s.ApplicationId)} › Runbook",$"<section class='panel runbook'><div class='runhead'><div><h2>{E(s.ApplicationId)} Configuration Runbook</h2><div class='muted'>Version {E(s.ApplicationVersion)}</div></div><button class='btn' onclick='window.print()'>Print / Save PDF</button></div><pre>{E(markdown)}</pre></section>","runbooks"));});
app.MapPost("/api/contracts/register",async(ApplicationConfigurationContract contract,HttpContext context,IConfigurationContractRegistrationStore store,ContractValidator validator,ISecretProvider secrets,CancellationToken ct)=>{var v=validator.Validate(contract); if(!v.IsValid)return Results.BadRequest(v); if(!DirectoryContractStore.IsSafeApplicationId(contract.ApplicationId))return Results.BadRequest(new{error="ApplicationId may contain only letters, digits, '.', '-' and '_'."}); string supplied=context.Request.Headers["X-Configuration-Registration-Key"].FirstOrDefault()??""; string? expected=await secrets.GetAsync($"configuration/registration/{contract.ApplicationId}",ct); if(string.IsNullOrWhiteSpace(expected)||!FixedTimeEquals(supplied,expected))return Results.Unauthorized(); try{return Results.Ok(await store.RegisterAsync(contract,ct));}catch(InvalidDataException ex){return Results.BadRequest(new{error=ex.Message});}});
app.MapGet("/api/contracts", async (IConfigurationContractStore store, CancellationToken ct) => Results.Ok(await store.LoadAllAsync(ct)));
app.MapGet("/api/report/{applicationId}", async (string applicationId, CommissioningService service, InstructionPackCatalog packs, CommissioningReportRenderer renderer, CancellationToken ct) => { var s = (await service.EvaluateAllAsync(ct)).FirstOrDefault(x => string.Equals(x.ApplicationId, applicationId, StringComparison.OrdinalIgnoreCase)); return s is null ? Results.NotFound() : Results.Text(renderer.RenderMarkdown(s, await packs.FindAsync(s.ApplicationId, s.ApplicationVersion, ct)), "text/markdown"); });
app.MapPost("/api/contracts/validate", (ApplicationConfigurationContract c, ContractValidator v) => Results.Ok(v.Validate(c)));
app.MapGet("/health", () => Results.Ok(new { status = "healthy", service = "Aegis.Configuration", displayName = "System Configuration" }));
app.Run();

static IResult Html(string v) => Results.Content(v, "text/html");
static string E(string? v) => HtmlEncoder.Default.Encode(v ?? "");
static bool FixedTimeEquals(string l, string r) { byte[] a = Encoding.UTF8.GetBytes(l), b = Encoding.UTF8.GetBytes(r); return a.Length == b.Length && CryptographicOperations.FixedTimeEquals(a, b); }
static string Active(string c, string i) => c == i ? " active" : "";
static string Css() => """
:root{--bg:#02070d;--panel:#071421;--line:#27547d;--ink:#eaf3ff;--muted:#9db7d4;--orange:#ff9b2f;--blue:#7896ff;--green:#50e59a;--yellow:#ffd05c;--red:#ff7777}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.4 Arial,sans-serif}a{color:inherit;text-decoration:none}.shell{display:grid;grid-template-columns:110px 1fr;min-height:100vh}.rail{padding:16px 8px}.cfglogo{width:48px;height:48px;margin:0 auto 18px;border-radius:50%;background:linear-gradient(135deg,var(--blue),#49d6c2);box-shadow:inset 0 0 0 10px #06111c}.rail nav{display:grid;gap:8px}.rail a,.btn{padding:12px 8px;border:1px solid var(--blue);border-radius:12px;text-align:center;font-weight:800}.rail a.active{background:var(--orange);color:#07101a}main{padding:14px;min-width:0}.mast{display:flex;gap:14px;align-items:center;border-bottom:5px solid var(--orange)}.mast .cfglogo{margin:0}.mast h1{margin:0;font-size:clamp(25px,4vw,42px)}.mast span,.panel p,small{color:var(--muted)}.crumb{margin:12px 0}.panel{border:2px solid var(--line);border-radius:16px;background:var(--panel);margin:12px 0;overflow:hidden}.appgrid{display:grid;grid-template-columns:1.3fr .8fr .7fr;gap:12px;padding:16px}.appgrid>div{border:1px solid var(--line);border-radius:10px;padding:12px}.appgrid h2{margin-top:0}.complete,.ok{color:var(--green)}.incomplete{color:var(--yellow)}.missing{color:var(--red)}dl{display:grid;grid-template-columns:120px 1fr;gap:4px}dt{font-weight:800}dd{margin:0}.actions{display:grid;gap:8px;align-content:start}.sectiontitle{padding:9px 14px;border-top:1px solid var(--line);color:var(--orange);font-weight:900}.tr{display:grid;grid-template-columns:1.5fr .6fr 1fr .7fr 1fr 1fr;border-top:1px solid var(--line)}.tr>div{padding:9px;overflow-wrap:anywhere}.tr small{display:block}.thead{font-weight:900;background:#122a3d}.mobiletop,.mobilebottom{display:none}.empty{padding:24px}.runbook{padding:16px}.runbook pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:850px){.appgrid{grid-template-columns:1fr 1fr}.actions{grid-column:1/-1}.tr{grid-template-columns:1.4fr .7fr 1fr .7fr}.tr>div:nth-child(5),.tr>div:nth-child(6){display:none}}@media(max-width:600px){.shell{display:block}.rail,.mast{display:none}.mobiletop{display:flex;position:sticky;top:0;z-index:5;align-items:center;gap:10px;padding:8px;background:#06111c;border-bottom:3px solid var(--orange)}.mobiletop .cfglogo{width:38px;height:38px;margin:0}.mobilebottom{display:grid;grid-template-columns:repeat(3,1fr);position:fixed;bottom:0;left:0;right:0;background:#06111c;padding:7px;gap:5px;border-top:3px solid var(--orange)}.mobilebottom a{padding:10px 4px;text-align:center}main{padding:8px 8px 75px}.appgrid{grid-template-columns:1fr}.actions{grid-column:auto}.table{padding:7px}.thead{display:none}.tr{display:block;border:1px solid var(--line);border-radius:10px;margin:7px 0;padding:7px}.tr>div{display:block!important;padding:3px}dl{grid-template-columns:105px 1fr}}@media print{.rail,.mobiletop,.mobilebottom,.mast{display:none!important}.shell{display:block}body{background:white;color:black}.panel{border:0}}
""";
static string Page(string title,string crumb,string content,string active) => "<!doctype html><html><head><title>" + E(title) + " · System Configuration</title><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><style>" + Css() + "</style></head><body><header class='mobiletop'><div class='cfglogo'></div><b>SYSTEM CONFIGURATION</b></header><div class='shell'><aside class='rail'><div class='cfglogo'></div><nav><a class='" + Active(active,"applications") + "' href='/'>APPLICATIONS</a><a class='" + Active(active,"runbooks") + "' href='/runbooks'>RUNBOOKS</a><a href='/api/contracts'>CONTRACTS</a></nav></aside><main><header class='mast'><div class='cfglogo'></div><div><h1>SYSTEM <b>CONFIGURATION</b></h1><span>KNOW WHAT IS REQUIRED. KNOW WHAT IS CONFIGURED.</span></div></header><div class='crumb'>⌂ &nbsp; " + crumb + "</div>" + content + "</main></div><nav class='mobilebottom'><a href='/'>APPLICATIONS</a><a href='/runbooks'>RUNBOOKS</a><a href='/api/contracts'>CONTRACTS</a></nav></body></html>";
static string RenderApplication(ApplicationConfigurationContract c, ConfigurationEvaluation e, bool detailsOnly = false)
{
    int required=c.Requirements.Count(x=>x.Required), rc=e.Requirements.Count(x=>x.Required&&x.State==ConfigurationState.Configured), optional=c.Requirements.Count(x=>!x.Required), oc=e.Requirements.Count(x=>!x.Required&&x.State==ConfigurationState.Configured); bool complete=e.IsComplete; string id=Uri.EscapeDataString(c.ApplicationId);
    string reqs=string.Join("",e.Requirements.Select(r=>$"<div class='tr'><div><b>{E(r.DisplayName)}</b><small>{E(r.Purpose)}</small></div><div>{(r.Required?"Required":"Optional")}</div><div>{E(r.Sensitive?"Protected / not displayed":r.SafeDisplayValue??(r.State==ConfigurationState.Configured?"Configured":"Not configured"))}</div><div class='{(r.State==ConfigurationState.Missing?"missing":"ok")}'>{E(r.State.ToString())}</div><div>{E(r.Example)}</div><div>{E(r.Message)}</div></div>"));
    string actions=detailsOnly?$"<a class='btn' href='/runbooks/{id}'>View Runbook</a><a class='btn' href='/'>Back</a>":$"<a class='btn' href='/applications/{id}'>View Configuration</a><a class='btn' href='/runbooks/{id}'>Runbook</a>";
    string registered=c.LastRegisteredAtUtc?.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss zzz")??"Legacy / not yet re-registered";
    return $"<section class='panel'><div class='appgrid'><div><h2>{E(c.DisplayName)}</h2><p>{E(c.Description??"Registered application")}</p><dl><dt>Application ID</dt><dd>{E(c.ApplicationId)}</dd><dt>Version</dt><dd>{E(c.Version)}</dd><dt>Site</dt><dd>{E(c.SiteId??"—")}</dd><dt>Instance</dt><dd>{E(c.InstanceId??"—")}</dd><dt>Last registration</dt><dd>{E(registered)}</dd></dl></div><div><h2 class='{(complete?"complete":"incomplete")}'>{(complete?"✓ COMPLETE":"● INCOMPLETE")}</h2><p>{rc}/{required} required · {oc}/{optional} optional</p></div><div class='actions'>{actions}</div></div><div class='sectiontitle'>Configuration Requirements</div><div class='table'><div class='tr thead'><div>Setting / Purpose</div><div>Requirement</div><div>Current Value</div><div>Status</div><div>Example</div><div>Notes</div></div>{reqs}</div></section>";
}
